using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;

namespace BandizipControl {
public static class SelfTests {
 static List<string> passed=new List<string>();static string root,source;
 static void Check(bool b,string s){if(!b)throw new Exception("TEST FAILED: "+s);}
 static void Pass(string s){passed.Add("PASS "+s);File.WriteAllLines(Path.Combine(root,"test-results.txt"),passed,new UTF8Encoding(false));}
 static string Copy(string name){string dir=Path.Combine(root,name);Directory.CreateDirectory(Path.Combine(dir,"data"));foreach(string f in Files.Allowed){string p=Path.Combine(source,f);if(File.Exists(p))File.Copy(p,Path.Combine(dir,f));}return dir;}
 static Analysis Scan(string p){return Analyzer.Scan(p,s=>{});}
 static void Refuses(Action a,string label){bool rejected=false;try{a();}catch{rejected=true;}Check(rejected,label);Pass(label);}
 static void AllOriginal(string p,Analysis a){Check(a.Files.All(f=>Util.FileHash(Files.Target(p,f.RelativePath))==f.OriginalHash),"original files restored");}
 static void Write64(byte[] b,int o,ulong v){Buffer.BlockCopy(BitConverter.GetBytes(v),0,b,o,8);}
 static void Write32(byte[] b,int o,uint v){Buffer.BlockCopy(BitConverter.GetBytes(v),0,b,o,4);}
 public static void Run(string originalDirectory,string outputDirectory){
  source=Path.GetFullPath(originalDirectory);root=Path.GetFullPath(outputDirectory);Check(!Directory.Exists(root)&&!File.Exists(root),"test output must be new");Directory.CreateDirectory(root);
  string exact=Copy("exact");var a=Scan(exact);Check(a.Files.Sum(f=>f.Patches.Count)==8,"eight structural patch locations");Pass("original fixture: all four features recognized without version/hash gates");
  var settings=new MemorySettings();string oldSettings=string.Join("|",settings.Read().Select(s=>s.Value));Engine.Apply(a,settings,s=>{},null);Check(Engine.State(exact,Files.LoadBackup(exact))=="Applied","applied state");Check(settings.State[0].Value=="2","disabled setting");Pass("apply: all files match planned hashes; registry simulated in memory");
  Refuses(()=>Engine.Apply(a,settings,s=>{},null),"repeated apply refused without re-patching");
  Refuses(()=>Engine.Restore(exact,settings,s=>{},n=>{if(n==1)throw new IOException("simulated restore failure");}),"restore fault injected after first file");Check(Engine.State(exact,Files.LoadBackup(exact))=="Applied","restore rollback preserves patched files");Pass("failed restore rolled back to previously patched state");
  Engine.Restore(exact,settings,s=>{},null);AllOriginal(exact,a);Check(string.Join("|",settings.Read().Select(s=>s.Value))==oldSettings,"registry restored");Pass("restore: byte-identical originals and original simulated settings");
  Engine.Apply(Scan(exact),settings,s=>{},null);Engine.Restore(exact,settings,s=>{},null);Pass("apply/restore cycle can repeat while retaining verified backup");
  string rollback=Copy("rollback");var r=Scan(rollback);var rs=new MemorySettings();Refuses(()=>Engine.Apply(r,rs,s=>{},n=>{if(n==1)throw new IOException("simulated write failure");}),"apply fault injected after first file");AllOriginal(rollback,r);Check(rs.State[0].Value=="1","registry untouched before file completion");Pass("failed apply rolled back files and preserved settings");
  string changed=Copy("changed-after-scan");var ch=Scan(changed);string chMain=Path.Combine(changed,"Bandizip.exe");byte[] cb=File.ReadAllBytes(chMain);cb[cb.Length-1]^=1;File.WriteAllBytes(chMain,cb);string chHash=Util.Hash(cb);Refuses(()=>Engine.Apply(ch,new MemorySettings(),s=>{},null),"file changed after scan is rejected before backup/write");Check(Util.FileHash(chMain)==chHash&&!Directory.Exists(Files.BackupDir(changed)),"no changes after failed validation");
  string meta=Copy("version-changed");foreach(string rel in new[]{"Bandizip.exe","Updater.exe"}){string p=Path.Combine(meta,rel);byte[] b=File.ReadAllBytes(p),needle=Encoding.Unicode.GetBytes("7.46.0.1");int count=0;for(int o=0;o<=b.Length-needle.Length;o++){if(b[o]!=needle[0])continue;bool ok=true;for(int k=1;k<needle.Length;k++)if(b[o+k]!=needle[k]){ok=false;break;}if(ok){b[o+needle.Length-2]=(byte)'9';count++;}}Check(count>0,"version fixture changed");File.WriteAllBytes(p,b);}Check(Scan(meta).Files.Sum(f=>f.Patches.Count)==8,"version ignored");Pass("changed FileVersion metadata recognized; no version restriction");
  string rebase=Copy("rebased");foreach(string rel in new[]{"Bandizip.exe","Updater.exe"}){string p=Path.Combine(rebase,rel);byte[] b=File.ReadAllBytes(p);var pe=new PeImage(b);Write64(b,pe.Optional+24,pe.ImageBase+0x10000000);File.WriteAllBytes(p,b);}var reb=Scan(rebase);Check(reb.Files[0].Patches.First().Address==a.Files[0].Patches.First().Address+0x10000000,"rebased VA generated");Pass("different PE image bases recognized; no fixed virtual addresses");
  string shifted=Copy("raw-layout-shifted");foreach(string rel in new[]{"Bandizip.exe","Updater.exe"}){string p=Path.Combine(shifted,rel);byte[] b=File.ReadAllBytes(p);var pe=new PeImage(b);int insert=(int)pe.Sections.Where(s=>s.Size>0).Min(s=>s.Offset);byte[] dst=new byte[b.Length+512];Buffer.BlockCopy(b,0,dst,0,insert);Buffer.BlockCopy(b,insert,dst,insert+512,b.Length-insert);int coff=(int)BitConverter.ToUInt32(b,60),table=coff+24+BitConverter.ToUInt16(b,coff+20);for(int k=0;k<pe.Sections.Count;k++){uint o=pe.Sections[k].Offset;if(o>=insert&&pe.Sections[k].Size>0)Write32(dst,table+k*40+20,o+512);}uint cert=pe.U32(pe.Directories+32);if(cert>=insert)Write32(dst,pe.Directories+32,cert+512);File.WriteAllBytes(p,dst);}var sh=Scan(shifted);Check(sh.Files[0].Patches.First().Offset==a.Files[0].Patches.First().Offset+512,"raw offset shifted");Pass("shifted file section offsets recognized; no fixed file offsets");
  string missing=Copy("missing-feature");string mp=Path.Combine(missing,"Bandizip.exe");byte[] mb=File.ReadAllBytes(mp);var ns=Encoding.Unicode.GetBytes("/nosleep");bool edited=false;for(int o=0;o<mb.Length-ns.Length;o++){if(mb[o]!=ns[0])continue;bool match=true;for(int k=1;k<ns.Length;k++)if(mb[o+k]!=ns[k]){match=false;break;}if(match){mb[o+2]=(byte)'x';edited=true;break;}}Check(edited,"removed seed");File.WriteAllBytes(mp,mb);Refuses(()=>Scan(missing),"missing required semantic feature rejected");
  string ambiguous=Copy("ambiguous-function");string ap=Path.Combine(ambiguous,"Bandizip.exe");byte[] ab=File.ReadAllBytes(ap);var api=new PeImage(ab);ulong launch=a.Files[0].Patches.First().Address;int pdata=api.Offset(api.ImageBase+api.U32(api.Directories+24));int selected=-1;for(int k=0;k<api.U32(api.Directories+28)/12;k++)if(api.U32(pdata+k*12)+api.ImageBase==launch){selected=k;break;}Check(selected>=0,"find launch function");Buffer.BlockCopy(ab,pdata+selected*12,ab,pdata,12);File.WriteAllBytes(ap,ab);Refuses(()=>Scan(ambiguous),"ambiguous duplicate function match rejected");
  string arch=Copy("wrong-architecture");string archp=Path.Combine(arch,"Bandizip.exe");byte[] archb=File.ReadAllBytes(archp);int archcoff=(int)BitConverter.ToUInt32(archb,60);archb[archcoff+4]=0x4c;archb[archcoff+5]=1;File.WriteAllBytes(archp,archb);Refuses(()=>Scan(arch),"unsupported architecture rejected instead of applying x64 code");
  string corrupt=Copy("corrupt-backup");var ca=Scan(corrupt);var cs=new MemorySettings();Engine.Apply(ca,cs,s=>{},null);string backup=Path.Combine(Files.BackupDir(corrupt),"original","Bandizip.exe");byte[] corruptb=File.ReadAllBytes(backup);corruptb[0]^=1;File.WriteAllBytes(backup,corruptb);Refuses(()=>Engine.Restore(corrupt,cs,s=>{},null),"corrupt backup refused before restore");Check(Util.FileHash(Path.Combine(corrupt,"Bandizip.exe"))==ca.Files[0].PatchedHash,"installed file untouched after corrupt backup");
  var dll=(byte[])File.ReadAllBytes(Path.Combine(source,"Bandizip.exe"));Refuses(()=>new PeImage(dll.Take(300).ToArray()),"truncated PE rejected");
  string runtime=Copy("runtime-ready");Engine.Apply(Scan(runtime),new MemorySettings(),s=>{},null);Pass("created patched runtime fixture using simulated registry for GUI smoke test");
  Pass("ALL TESTS PASSED; no installed application or real registry was modified by self-tests");
 }
}
}
